// Node arena: the safe-Rust stand-in for earcut.hpp's `Node*` / ObjectPool.
//
// A NodeId is a plain index into an APPEND-ONLY `Vec<Node>`. Because nothing is
// ever removed from the arena, a NodeId behaves exactly like a raw pointer that
// is never freed -- which is precisely the lifetime model earcut.hpp relies on.

pub type NodeId = usize;

/// The "nullptr" sentinel.
pub const NIL: NodeId = usize::MAX;

pub struct Node {
    /// Vertex index reported in the output.
    pub i: u32,
    pub x: f64,
    pub y: f64,
    /// Previous / next node in the polygon ring. Always valid after insert_node.
    pub prev: NodeId,
    pub next: NodeId,
    /// z-order curve value; 0 means "not computed yet" (memoisation sentinel).
    pub z: i32,
    /// Previous / next node in the z-order linked list. NIL-able.
    pub prev_z: NodeId,
    pub next_z: NodeId,
    pub steiner: bool,
}

pub struct Earcut {
    pub arena: Vec<Node>,
    pub indices: Vec<u32>,
    /// Running vertex-index offset across rings.
    pub vertices: usize,
    pub hashing: bool,
    pub min_x: f64,
    pub min_y: f64,
    pub max_x: f64,
    pub max_y: f64,
    pub inv_size: f64,
}

impl Earcut {
    pub fn new() -> Earcut {
        Earcut {
            arena: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    // ---- tiny copy accessors -------------------------------------------------
    // Never hold a `&mut Node` across a call to another `&mut self` method;
    // read every f64 you need into a local BEFORE mutating anything.

    #[inline]
    pub fn x(&self, p: NodeId) -> f64 {
        self.arena[p].x
    }
    #[inline]
    pub fn y(&self, p: NodeId) -> f64 {
        self.arena[p].y
    }
    #[inline]
    pub fn idx(&self, p: NodeId) -> u32 {
        self.arena[p].i
    }
    #[inline]
    pub fn pv(&self, p: NodeId) -> NodeId {
        self.arena[p].prev
    }
    #[inline]
    pub fn nx(&self, p: NodeId) -> NodeId {
        self.arena[p].next
    }
    #[inline]
    pub fn zz(&self, p: NodeId) -> i32 {
        self.arena[p].z
    }
    #[inline]
    pub fn pz(&self, p: NodeId) -> NodeId {
        self.arena[p].prev_z
    }
    #[inline]
    pub fn nz(&self, p: NodeId) -> NodeId {
        self.arena[p].next_z
    }

    /// Append a fresh node to the arena, linking it AFTER `last` (or as a
    /// self-loop when `last == NIL`). Returns the new node.
    pub fn insert_node(&mut self, i: usize, px: f64, py: f64, last: NodeId) -> NodeId {
        let p = self.arena.len();
        self.arena.push(Node {
            i: i as u32,
            x: px,
            y: py,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        if last == NIL {
            self.arena[p].prev = p;
            self.arena[p].next = p;
        } else {
            let ln = self.arena[last].next;
            self.arena[p].next = ln;
            self.arena[p].prev = last;
            self.arena[ln].prev = p;
            self.arena[last].next = p;
        }
        p
    }

    /// Unlink `p` from the ring and from the z chain.
    ///
    /// This deliberately does NOT clear p's own prev/next: filter_points and
    /// cure_local_intersections both read the STALE links of a just-removed
    /// node. Nothing is ever removed from the arena itself.
    pub fn remove_node(&mut self, p: NodeId) {
        let pp = self.arena[p].prev;
        let pn = self.arena[p].next;
        self.arena[pn].prev = pp;
        self.arena[pp].next = pn;

        let pz = self.arena[p].prev_z;
        let nz = self.arena[p].next_z;
        if pz != NIL {
            self.arena[pz].next_z = nz;
        }
        if nz != NIL {
            self.arena[nz].prev_z = pz;
        }
    }

    /// Exact f64 equality on both coordinates -- no epsilon.
    #[inline]
    pub fn equals(&self, p1: NodeId, p2: NodeId) -> bool {
        self.arena[p1].x == self.arena[p2].x && self.arena[p1].y == self.arena[p2].y
    }
}

// Geometric predicates. Every comparison operator and sign convention here is
// load-bearing: `area(prev, ear, next) < 0` is the convexity test for this
// winding, and point_in_triangle is INCLUSIVE on all three cross products.

use crate::node::{Earcut, NodeId};

/// Signed area of the triangle p-q-r, doubled. NEGATIVE means convex for the
/// winding earcut produces.
#[inline]
pub fn area_of(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

#[inline]
pub fn sign(v: f64) -> i32 {
    if v > 0.0 {
        1
    } else if v < 0.0 {
        -1
    } else {
        0
    }
}

/// Inclusive point-in-triangle: a point exactly on an edge or at a vertex
/// counts as inside.
#[inline]
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

impl Earcut {
    #[inline]
    pub fn area(&self, p: NodeId, q: NodeId, r: NodeId) -> f64 {
        let a = &self.arena[p];
        let b = &self.arena[q];
        let c = &self.arena[r];
        (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y)
    }

    /// Is `q` inside the axis-aligned bounding box of the segment p..r?
    pub fn on_segment(&self, p: NodeId, q: NodeId, r: NodeId) -> bool {
        let (px, py) = (self.x(p), self.y(p));
        let (qx, qy) = (self.x(q), self.y(q));
        let (rx, ry) = (self.x(r), self.y(r));
        qx <= px.max(rx) && qx >= px.min(rx) && qy <= py.max(ry) && qy >= py.min(ry)
    }

    /// Do the segments p1q1 and p2q2 intersect?
    pub fn intersects(&self, p1: NodeId, q1: NodeId, p2: NodeId, q2: NodeId) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true; // p1, q1 and p2 are collinear and p2 lies on p1q1
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true; // p1, q1 and q2 are collinear and q2 lies on p1q1
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true; // p2, q2 and p1 are collinear and p1 lies on p2q2
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true; // p2, q2 and q1 are collinear and q1 lies on p2q2
        }
        false
    }

    /// Does the polygon edge ring intersect the diagonal a-b?
    /// Compares `.i` values, not NodeIds: split_polygon mints clones that share
    /// an `.i` and must be treated as the same vertex here.
    pub fn intersects_polygon(&self, a: NodeId, b: NodeId) -> bool {
        let ai = self.idx(a);
        let bi = self.idx(b);
        let mut p = a;
        loop {
            let pn = self.nx(p);
            let pi = self.idx(p);
            let pni = self.idx(pn);
            if pi != ai && pni != ai && pi != bi && pni != bi && self.intersects(p, pn, a, b) {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    /// Is the diagonal a-b locally inside the polygon at a? Deliberately
    /// asymmetric: AND/inclusive on the convex branch, OR/strict on the reflex.
    pub fn locally_inside(&self, a: NodeId, b: NodeId) -> bool {
        let ap = self.pv(a);
        let an = self.nx(a);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// Ray-cast the midpoint of a-b against the ring.
    pub fn middle_inside(&self, a: NodeId, b: NodeId) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let pn = self.nx(p);
            let (cx, cy) = (self.x(p), self.y(p));
            let (nx_, ny) = (self.x(pn), self.y(pn));
            if ((cy > py) != (ny > py)) && ny != cy && (px < (nx_ - cx) * (py - cy) / (ny - cy) + cx)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Is the diagonal a-b a valid, non-self-intersecting cut of the polygon?
    pub fn is_valid_diagonal(&self, a: NodeId, b: NodeId) -> bool {
        let bi = self.idx(b);
        let ap = self.pv(a);
        let an = self.nx(a);
        let bp = self.pv(b);
        let bn = self.nx(b);
        self.idx(an) != bi
            && self.idx(ap) != bi
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// Whether sector in vertex m contains sector in vertex p, in the same coords.
    pub fn sector_contains_sector(&self, m: NodeId, p: NodeId) -> bool {
        self.area(self.pv(m), m, self.pv(p)) < 0.0 && self.area(self.nx(p), m, self.nx(m)) < 0.0
    }
}

// z-order (Morton) curve machinery: the O(1) candidate index that keeps
// is_ear_hashed from degenerating into an O(n) scan per ear.

use crate::node::{Earcut, NodeId, NIL};

impl Earcut {
    /// z-order of a point given the bbox captured in `min_x`/`min_y`/`inv_size`.
    /// 15 bits per axis, interleaved.
    pub fn z_order(&self, xf: f64, yf: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((xf - self.min_x) * self.inv_size) as i32;
        let mut y = ((yf - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    /// Interlink every node with the next and previous in z-order, then sort
    /// that chain. The sorted head is DELIBERATELY discarded: is_ear_hashed only
    /// ever navigates outward from `ear` via prev_z/next_z.
    pub fn index_curve(&mut self, start: NodeId) {
        let mut p = start;
        loop {
            if self.arena[p].z == 0 {
                let (px, py) = (self.x(p), self.y(p));
                self.arena[p].z = self.z_order(px, py);
            }
            let pp = self.arena[p].prev;
            let pn = self.arena[p].next;
            self.arena[p].prev_z = pp;
            self.arena[p].next_z = pn;
            p = pn;
            if p == start {
                break;
            }
        }

        // cut the circular z chain open into a linear one
        let pz = self.arena[p].prev_z;
        self.arena[pz].next_z = NIL;
        self.arena[p].prev_z = NIL;

        self.sort_linked(p);
    }

    /// Simon Tatham's iterative bottom-up merge sort on the prev_z/next_z chain.
    /// The `<=` comparison keeps it STABLE, which matters because equal z values
    /// are common (the Morton grid is only 15 bits per axis).
    pub fn sort_linked(&mut self, list0: NodeId) -> NodeId {
        let mut list = list0;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.arena[q].next_z;
                    if q == NIL {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.arena[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.arena[p].next_z;
                        p_size -= 1;
                    } else if self.arena[p].z <= self.arena[q].z {
                        e = p;
                        p = self.arena[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.arena[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.arena[tail].next_z = e;
                    } else {
                        list = e;
                    }
                    self.arena[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            if tail != NIL {
                self.arena[tail].next_z = NIL;
            }

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }
}

// Ring construction and surgery: linked_list, filter_points, split_polygon and
// the whole hole-elimination pipeline.

use crate::node::{Earcut, Node, NodeId, NIL};
use crate::points::Pt;
use crate::predicates::point_in_triangle;

impl Earcut {
    /// Create a circular doubly linked list from polygon points in the
    /// specified winding order. Returns the LAST INSERTED node -- for forward
    /// insertion that is vertex len-1, for reverse insertion it is vertex 0.
    pub fn linked_list(&mut self, points: &[Pt], clockwise: bool) -> NodeId {
        let len = points.len();
        let mut sum = 0.0f64;
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = &points[i]; // current
            let p2 = &points[j]; // previous
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // link points into the circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                let v = self.vertices + i;
                last = self.insert_node(v, points[i][0], points[i][1], last);
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                let v = self.vertices + i;
                last = self.insert_node(v, points[i][0], points[i][1], last);
            }
        }

        if last != NIL {
            let ln = self.arena[last].next;
            if self.equals(last, ln) {
                self.remove_node(last);
                last = ln;
            }
        }

        self.vertices += len;
        last
    }

    /// Eliminate colinear or duplicate points. `end0 == NIL` means "default to
    /// start". Reads the STALE `.prev` of a just-removed node -- by design.
    pub fn filter_points(&mut self, start: NodeId, end0: NodeId) -> NodeId {
        if start == NIL {
            return NIL;
        }
        let mut end = if end0 == NIL { start } else { end0 };

        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.arena[p].next;
            let pp = self.arena[p].prev;
            if !self.arena[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                p = self.arena[p].prev;
                end = p;

                if p == self.arena[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.arena[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the
    /// same ring it splits it in two. Mints TWO new arena nodes that duplicate
    /// a/b's `.i` -- intentional, both halves share the diagonal endpoints.
    pub fn split_polygon(&mut self, a: NodeId, b: NodeId) -> NodeId {
        let a2 = self.arena.len();
        self.arena.push(Node {
            i: self.arena[a].i,
            x: self.arena[a].x,
            y: self.arena[a].y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        let b2 = self.arena.len();
        self.arena.push(Node {
            i: self.arena[b].i,
            x: self.arena[b].x,
            y: self.arena[b].y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });

        let an = self.arena[a].next;
        let bp = self.arena[b].prev;

        self.arena[a].next = b;
        self.arena[b].prev = a;

        self.arena[a2].next = an;
        self.arena[an].prev = a2;

        self.arena[b2].next = a2;
        self.arena[a2].prev = b2;

        self.arena[bp].next = b2;
        self.arena[b2].prev = bp;

        b2
    }

    /// Find the leftmost node of a polygon ring.
    pub fn get_leftmost(&self, start: NodeId) -> NodeId {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.x(p) < self.x(leftmost)
                || (self.x(p) == self.x(leftmost) && self.y(p) < self.y(leftmost))
            {
                leftmost = p;
            }
            p = self.nx(p);
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Link every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    pub fn eliminate_holes(&mut self, polygon: &[Vec<Pt>], outer_node0: NodeId) -> NodeId {
        let mut outer_node = outer_node0;
        let mut queue: Vec<NodeId> = Vec::new();

        for i in 1..polygon.len() {
            let list = self.linked_list(&polygon[i], false);
            if list != NIL {
                if list == self.arena[list].next {
                    self.arena[list].steiner = true;
                }
                let lm = self.get_leftmost(list);
                queue.push(lm);
            }
        }

        // process holes from left to right; keyed on x only, as in the C++
        {
            let arena = &self.arena;
            queue.sort_by(|&a, &b| {
                arena[a]
                    .x
                    .partial_cmp(&arena[b].x)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
        }

        for k in 0..queue.len() {
            outer_node = self.eliminate_hole(queue[k], outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring,
    /// and link it.
    pub fn eliminate_hole(&mut self, hole: NodeId, outer_node: NodeId) -> NodeId {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }
        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.arena[bridge_reverse].next;
        self.filter_points(bridge_reverse, brn);
        let bn = self.arena[bridge].next;
        self.filter_points(bridge, bn)
    }

    /// David Eberly's algorithm for finding a bridge between a hole and an
    /// outer polygon.
    pub fn find_hole_bridge(&self, hole: NodeId, outer_node: NodeId) -> NodeId {
        let mut p = outer_node;
        let hx = self.x(hole);
        let hy = self.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost point to
        // the left; segment's endpoint with lesser x will be potential
        // connection point
        loop {
            let pn = self.nx(p);
            let py = self.y(p);
            let ny = self.y(pn);
            if hy <= py && hy >= ny && ny != py {
                let px = self.x(p);
                let nxx = self.x(pn);
                let xi = px + (hy - py) * (nxx - px) / (ny - py);
                if xi <= hx && xi > qx {
                    qx = xi;
                    m = if px < nxx { p } else { pn };
                    if xi == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole point, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the point of the minimum angle with
        // the ray as connection point
        let stop = m;
        let mx = self.x(m);
        let my = self.y(m);
        let mut tan_min = f64::INFINITY;

        p = m;
        loop {
            let px = self.x(p);
            let py = self.y(p);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential
                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.x(m) || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }
            p = self.nx(p);
            if p == stop {
                break;
            }
        }

        m
    }
}

// The ear-clipping sweep, the two ear tests, the pass 0/1/2 fallback chain, and
// the top-level driver that mirrors earcut.hpp's `operator()`.

use crate::node::{Earcut, NodeId, NIL};
use crate::points::Pt;
use crate::predicates::point_in_triangle;

impl Earcut {
    /// Top level: mirrors earcut.hpp's `operator()(const Polygon&)`.
    pub fn run(&mut self, polygon: &[Vec<Pt>]) {
        self.indices.clear();
        self.vertices = 0;

        if polygon.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i: usize = 0;
        while threshold >= 0 && i < polygon.len() {
            threshold = threshold.wrapping_sub(polygon[i].len() as i32);
            len += polygon[i].len();
            i += 1;
        }

        // Capacity hints only -- these can never change behaviour.
        // C++: nodes.reset(len * 3 / 2 - polygon[0].size() / 2)
        let node_cap = len
            .saturating_mul(3)
            .saturating_div(2)
            .saturating_sub(polygon[0].len() / 2);
        self.arena.reserve(node_cap);
        // The real output is 3*(len-2) indices; reserve that up front so the
        // hot loop never reallocates (C++ under-reserves here).
        self.indices.reserve(len.saturating_mul(3));

        let mut outer_node = self.linked_list(&polygon[0], true);
        if outer_node == NIL || self.arena[outer_node].prev == self.arena[outer_node].next {
            return;
        }

        if polygon.len() > 1 {
            outer_node = self.eliminate_holes(polygon, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.arena[outer_node].next;
            self.min_x = self.x(outer_node);
            self.max_x = self.min_x;
            self.min_y = self.y(outer_node);
            self.max_y = self.min_y;
            loop {
                let px = self.x(p);
                let py = self.y(p);
                if px < self.min_x {
                    self.min_x = px;
                }
                if py < self.min_y {
                    self.min_y = py;
                }
                if px > self.max_x {
                    self.max_x = px;
                }
                if py > self.max_y {
                    self.max_y = py;
                }
                p = self.arena[p].next;
                if p == outer_node {
                    break;
                }
            }

            // minX, minY and invSize are later used to transform coords into
            // integers for z-order calculation
            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    pub fn earcut_linked(&mut self, ear0: NodeId, pass: i32) {
        if ear0 == NIL {
            return;
        }
        let mut ear = ear0;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.arena[ear].prev != self.arena[ear].next {
            let prev = self.arena[ear].prev;
            let next = self.arena[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.arena[prev].i);
                self.indices.push(self.arena[ear].i);
                self.indices.push(self.arena[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.arena[next].next;
                stop = self.arena[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let e = self.filter_points(ear, NIL);
                    self.earcut_linked(e, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let e = self.filter_points(ear, NIL);
                    let e2 = self.cure_local_intersections(e);
                    self.earcut_linked(e2, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    pub fn is_ear(&self, ear: NodeId) -> bool {
        let a = self.pv(ear);
        let b = ear;
        let c = self.nx(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.x(a), self.y(a));
        let (bx, by) = (self.x(b), self.y(b));
        let (cx, cy) = (self.x(c), self.y(c));

        // now make sure we don't have other points inside the potential ear
        let stop = self.pv(ear);
        let mut p = self.nx(self.nx(ear));
        while p != stop {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0
            {
                return false;
            }
            p = self.nx(p);
        }
        true
    }

    /// Ear test restricted to the z-order neighbourhood of the ear's bbox.
    pub fn is_ear_hashed(&self, ear: NodeId) -> bool {
        let a = self.pv(ear);
        let b = ear;
        let c = self.nx(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.x(a), self.y(a));
        let (bx, by) = (self.x(b), self.y(b));
        let (cx, cy) = (self.x(c), self.y(c));

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.pz(ear);
        let mut n = self.nz(ear);

        while p != NIL && self.zz(p) >= min_z && n != NIL && self.zz(n) <= max_z {
            if p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0
            {
                return false;
            }
            p = self.pz(p);

            if n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.pv(n), n, self.nx(n)) >= 0.0
            {
                return false;
            }
            n = self.nz(n);
        }

        // look for remaining points in decreasing z-order
        while p != NIL && self.zz(p) >= min_z {
            if p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0
            {
                return false;
            }
            p = self.pz(p);
        }

        // look for remaining points in increasing z-order
        while n != NIL && self.zz(n) <= max_z {
            if n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.pv(n), n, self.nx(n)) >= 0.0
            {
                return false;
            }
            n = self.nz(n);
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    pub fn cure_local_intersections(&mut self, start0: NodeId) -> NodeId {
        let mut start = start0;
        let mut p = start;
        loop {
            let a = self.arena[p].prev;
            let pn = self.arena[p].next;
            let b = self.arena[pn].next;

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.arena[a].i);
                self.indices.push(self.arena[p].i);
                self.indices.push(self.arena[b].i);

                // remove two nodes involved
                self.remove_node(p);
                let stale_next = self.arena[p].next;
                self.remove_node(stale_next);

                p = b;
                start = b;
            }

            p = self.arena[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Try splitting polygon into two and triangulate them independently.
    pub fn split_earcut(&mut self, start: NodeId) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let an = self.arena[a].next;
            let mut b = self.arena[an].next;
            let a_prev = self.arena[a].prev;
            while b != a_prev {
                if self.arena[a].i != self.arena[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a2 = self.arena[a].next;
                    a = self.filter_points(a, a2);
                    let c2 = self.arena[c].next;
                    c = self.filter_points(c, c2);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.arena[b].next;
            }
            a = self.arena[a].next;
            if a == start {
                break;
            }
        }
    }
}
